const orders = $input.first().json.data || [];
const today = new Date().toDateString();
const todayOrders = orders.filter(o => new Date(o.createdAt).toDateString() === today);
const total = todayOrders.reduce((s, o) => s + Number(o.total || 0), 0);
const paid = todayOrders.filter(o => ['PAYE','EN_PREPARATION','EN_LIVRAISON','LIVREE'].includes(o.status));
const pending = todayOrders.filter(o => o.status === 'PRE_CONFIRMEE');
const delivered = todayOrders.filter(o => o.status === 'LIVREE');
const ca = paid.reduce((s, o) => s + Number(o.total || 0), 0);
return [{ json: {
  date: new Date().toLocaleDateString('fr-FR'),
  nb_commandes: todayOrders.length,
  nb_payees: paid.length,
  nb_en_attente: pending.length,
  nb_livrees: delivered.length,
  ca_fcfa: ca.toLocaleString('fr-FR'),
  total_commandes_fcfa: total.toLocaleString('fr-FR')
}}];
